CREATE OR REPLACE FUNCTION sync_note_customer_note() RETURNS TRIGGER AS $$
BEGIN
  -- Propagate old‑version note change to customer_note if it is NULL
  IF NEW.note IS DISTINCT FROM COALESCE(OLD.note, '') THEN
    IF NEW.customer_note IS NULL THEN
      NEW.customer_note := NEW.note;
    ELSE
      NEW.customer_note := COALESCE(NEW.customer_note, NEW.note);
    END IF;
  END IF;
  -- Propagate new‑version customer_note change to note if it is NULL
  IF NEW.customer_note IS DISTINCT FROM COALESCE(OLD.customer_note, '') THEN
    IF NEW.note IS NULL THEN
      NEW.note := NEW.customer_note;
    ELSE
      NEW.note := COALESCE(NEW.note, NEW.customer_note);
    END IF;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
